   410	  it("throttles idleTimeout reseals to once per half window", async () => {
   411	    const t0 = Date.parse("2030-01-01T00:00:00Z");
   412	    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
   413	    // Every seal runs exactly one `subtle.encrypt` (see `iron-crypto.ts`)
   414	    const encrypt = vi.spyOn(globalThis.crypto.subtle, "encrypt");
   415	    try {
   416	      const config: SessionConfig = {
   417	        name: "h3-throttle",
   418	        password: sessionConfig.password,
   419	        idleTimeout: 60,
   420	      };
   421	      t.app.get("/throttle", async (event) => {
   422	        const session = await useSession(event, config);
   423	        return { hits: session.data.hits || 0 };
   424	      });
   425	      t.app.get("/throttle-write", async (event) => {
   426	        const session = await useSession(event, config);
   427	        await session.update((data) => ({ hits: (data.hits || 0) + 1 }));
   428	        return { hits: session.data.hits };
   429	      });
   430	      const throttleCookie = (res: Response) =>
   431	        res.headers.getSetCookie().find((c) => c.startsWith("h3-throttle="));
   432	
   433	      // t=0: new session, sealed once
   434	      const res1 = await t.fetch("/throttle");
   435	      expect(encrypt).toHaveBeenCalledTimes(1);
   436	      let cookie = throttleCookie(res1)!;
   437	      expect(cookie).toContain(`Expires=${new Date(t0 + 60_000).toUTCString()}`);
   438	
   439	      // t=10s: less than half the window is used, so reading does not reseal —
   440	      // and sets no cookie at all, leaving the response cacheable
   441	      vi.setSystemTime(t0 + 10_000);
   442	      encrypt.mockClear();
   443	      const res2 = await t.fetch("/throttle", { headers: { Cookie: cookie } });
   444	      expect(await res2.json()).toMatchObject({ hits: 0 });
   445	      expect(encrypt).not.toHaveBeenCalled();
   446	      expect(throttleCookie(res2)).toBeUndefined();
   447	
   448	      // t=10s: a write seals once — not once to slide and again for the update —
   449	      // and slides the window as a side effect of restamping `lastSeenAt`
   450	      encrypt.mockClear();
   451	      const res3 = await t.fetch("/throttle-write", { headers: { Cookie: cookie } });
   452	      expect(await res3.json()).toMatchObject({ hits: 1 });
   453	      expect(encrypt).toHaveBeenCalledTimes(1);
   454	      cookie = throttleCookie(res3)!;
   455	      expect(cookie).toContain(`Expires=${new Date(t0 + 70_000).toUTCString()}`);
   456	
   457	      // t=45s: 35s of the window used, so reading reseals and slides
   458	      vi.setSystemTime(t0 + 45_000);
   459	      encrypt.mockClear();
   460	      const res4 = await t.fetch("/throttle", { headers: { Cookie: cookie } });
   461	      expect(await res4.json()).toMatchObject({ hits: 1 });
   462	      expect(encrypt).toHaveBeenCalledTimes(1);
   463	      cookie = throttleCookie(res4)!;
   464	      expect(cookie).toContain(`Expires=${new Date(t0 + 105_000).toUTCString()}`);
   465	
   466	      // t=100s: 55s idle since that reseal, so the session is still alive
   467	      vi.setSystemTime(t0 + 100_000);
   468	      const res5 = await t.fetch("/throttle", { headers: { Cookie: cookie } });
   469	      expect(await res5.json()).toMatchObject({ hits: 1 });
   470	    } finally {
   471	      encrypt.mockRestore();
   472	      vi.useRealTimers();
   473	    }
   474	  });
